using System;using System.Collections.Generic;using UnityEngine;
namespace NWD.Missions {public enum ObjectiveType{ReachArea,HoldArea,KillCount,Interact,Defend,Escape,SurviveTimer,CinematicTrigger}public enum ObjectiveState{Locked,Active,Completed,Failed}
 [CreateAssetMenu(menuName="NWD/Objective")]public sealed class ObjectiveDefinition:ScriptableObject{public string stableId;public ObjectiveType type;public string text;public List<string> prerequisites=new();public bool persistent;}
 public sealed class ObjectiveRuntime{public readonly ObjectiveDefinition Definition;public ObjectiveState State{get;private set;}public float Progress{get;private set;}public event Action Started,Completed,Failed;public ObjectiveRuntime(ObjectiveDefinition d){Definition=d;}public bool Start(){if(State!=ObjectiveState.Locked)return false;State=ObjectiveState.Active;Started?.Invoke();return true;}public bool SetProgress(float p){if(State!=ObjectiveState.Active)return false;Progress=Mathf.Clamp01(p);if(Progress>=1){State=ObjectiveState.Completed;Completed?.Invoke();}return true;}public bool Fail(){if(State!=ObjectiveState.Active)return false;State=ObjectiveState.Failed;Failed?.Invoke();return true;}}
}
